{"explanation":"Draw a line through the top vertex C that runs parallel to the bottom side AB. Where the two slanted sides cross the two parallel lines, they make alternate interior angles, which are equal. So a copy of angle A (blue) and a copy of angle B (green) fit at C, one on each side of angle C (red). The three angles now sit side by side along a straight line, and a straight line is 180°. That's why the sum is always 180°, whatever shape the triangle has. Drag the yellow corners to try it: the angles change, the sum doesn't. This only works on a flat plane. On a curved surface like a sphere, there's no single parallel line through C, so the sum can be different.","manimCode":"const N = 24;
const R = 0.6;
function sub(p, q) { return [p[0]-q[0], p[1]-q[1], 0]; }
function unit(v) { const l = Math.hypot(v[0], v[1]) || 1; return [v[0]/l, v[1]/l, 0]; }
function sectorVerts(c, d1, d2, r) {
  const a1 = Math.atan2(d1[1], d1[0]);
  let a2 = Math.atan2(d2[1], d2[0]);
  let d = a2 - a1;
  while (d > Math.PI) d -= 2*Math.PI;
  while (d <= -Math.PI) d += 2*Math.PI;
  const pts = [[c[0], c[1], 0]];
  for (let i = 0; i <= N; i++) {
    const a = a1 + d * i / N;
    pts.push([c[0] + r*Math.cos(a), c[1] + r*Math.sin(a), 0]);
  }
  return pts;
}
function angleBetween(u, v) {
  const a = unit(u), b = unit(v);
  return Math.acos(Math.max(-1, Math.min(1, a[0]*b[0] + a[1]*b[1])));
}
function mkSector(col) {
  const p = new Polygon({ vertices: sectorVerts([0,0,0],[1,0,0],[0,1,0],R), color: col });
  p.setFill(col, 0.55); p.setStrokeWidth(1);
  return p;
}

const dotA = new Dot({ point: [-3, -1.8, 0], color: YELLOW });
const dotB = new Dot({ point: [2.5, -1.8, 0], color: YELLOW });
const dotC = new Dot({ point: [-0.5, 1.5, 0], color: YELLOW });

const tri = new Polygon({ vertices: [dotA.getCenter(), dotB.getCenter(), dotC.getCenter()], color: WHITE });
tri.setFill(GRAY, 0.15);

const parLine = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: GRAY });
parLine.setStrokeWidth(2); parLine.setFillOpacity(0);

const secA = mkSector(BLUE), secB = mkSector(GREEN), secC = mkSector(RED);
const copyA = mkSector(BLUE), copyB = mkSector(GREEN);

let info = null;
let sumLabel = null;

function update() {
  const A = dotA.getCenter(), B = dotB.getCenter(), C = dotC.getCenter();
  tri.setVertices([A, B, C]);
  const u = unit(sub(B, A));
  const mu = [-u[0], -u[1], 0];
  parLine.setVertices([[C[0]-3.5*u[0], C[1]-3.5*u[1], 0], [C[0]+3.5*u[0], C[1]+3.5*u[1], 0]]);
  secA.setVertices(sectorVerts(A, sub(B, A), sub(C, A), R));
  secB.setVertices(sectorVerts(B, sub(A, B), sub(C, B), R));
  secC.setVertices(sectorVerts(C, sub(A, C), sub(B, C), R));
  copyA.setVertices(sectorVerts(C, mu, sub(A, C), R*0.85));
  copyB.setVertices(sectorVerts(C, sub(B, C), u, R*0.85));

  const a = angleBetween(sub(B, A), sub(C, A)) * 180 / Math.PI;
  const b = angleBetween(sub(A, B), sub(C, B)) * 180 / Math.PI;
  const c = 180 - a - b;
  if (info) scene.remove(info);
  if (sumLabel) scene.remove(sumLabel);
  info = new Text({ text: 'A = ' + a.toFixed(1) + '°   B = ' + b.toFixed(1) + '°   C = ' + c.toFixed(1) + '°', color: WHITE, fontSize: 26 });
  info.moveTo([0, -3.0, 0]);
  sumLabel = new Text({ text: 'A + B + C = ' + (a + b + c).toFixed(1) + '°', color: YELLOW, fontSize: 30 });
  sumLabel.moveTo([0, -3.55, 0]);
  scene.add(info, sumLabel);
}

const title = new Text({ text: 'Copies of A and B at C make a straight line', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.5, 0]);

update();
scene.add(title, parLine, tri, secA, secB, secC, copyA, copyB, dotA, dotB, dotC);

const lab = (s, col) => new Text({ text: s, color: col, fontSize: 24 });
const lA = lab('A', BLUE), lB = lab('B', GREEN), lC = lab('C', RED);
scene.add(lA, lB, lC);
function placeLabels() {
  const A = dotA.getCenter(), B = dotB.getCenter(), C = dotC.getCenter();
  const g = [(A[0]+B[0]+C[0])/3, (A[1]+B[1]+C[1])/3];
  [[lA, A], [lB, B], [lC, C]].forEach(([l, P]) => {
    const d = unit([P[0]-g[0], P[1]-g[1], 0]);
    l.moveTo([P[0] + 0.35*d[0], P[1] + 0.35*d[1], 0]);
  });
}
placeLabels();

const opts = { constrainX: [-5.5, 5.5], constrainY: [-2.4, 2.9], onDrag: () => { update(); placeLabels(); } };
makeDraggable(dotA, scene, opts);
makeDraggable(dotB, scene, opts);
makeDraggable(dotC, scene, opts);

await scene.wait(999999);"}

